# ════════════════════════════════════════════════════════════════
# CHAPTER 3: COMPLETE SETUP WITH DEEP EXPLANATION
# ════════════════════════════════════════════════════════════════
# pip install openai
# No other packages needed!

import os
import json
import math
import time
from openai import OpenAI

client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

# ════════════════════════════════════════════════════════════════
# PART A: The Actual Python Functions
# ════════════════════════════════════════════════════════════════
#
# These are NORMAL Python functions. Nothing special about them.
# The "magic" comes LATER when we describe them to OpenAI in JSON.
#
# RULE: Functions must accept keyword arguments (**kwargs style)
#       because OpenAI sends args as a JSON dict, and we unpack
#       that dict with **args when calling the function.
# ════════════════════════════════════════════════════════════════

def calculator(expression: str) -> str:
    # WHY THIS EXISTS:
    # OpenAI's GPT can do math but sometimes makes errors on
    # very large numbers. We give it a real Python eval() to be sure.
    #
    # SECURITY NOTE: Never use plain eval() in production!
    # We pass {"__builtins__": {}} to disable ALL built-in functions
    # so a user can't inject: "__import__('os').system('rm -rf /')"
    # We only allow 'math' module functions like math.sqrt, math.pi
    try:
        safe_globals = {"__builtins__": {}, "math": math}
        result = eval(expression, safe_globals)
        return f"Calculated result: {result}"
    except ZeroDivisionError:
        return "Error: Cannot divide by zero"
    except SyntaxError:
        return f"Error: '{expression}' is not a valid math expression"
    except Exception as e:
        return f"Error: {str(e)}"

def weather_tool(city: str) -> str:
    # WHY THIS EXISTS:
    # GPT's training data has a cutoff. It cannot know TODAY's weather.
    # This simulates a real weather API call.
    # In production: replace with requests.get("api.openweathermap.org/...")
    #
    # NOTE: We normalize city name with .lower().strip() because
    # OpenAI might send "London" or "london" or " London "
    city_normalized = city.lower().strip()
    weather_database = {
        "london":    {"temp": "15°C", "condition": "cloudy",       "humidity": "78%"},
        "new york":  {"temp": "22°C", "condition": "sunny",        "humidity": "55%"},
        "tokyo":     {"temp": "28°C", "condition": "humid",        "humidity": "85%"},
        "paris":     {"temp": "18°C", "condition": "partly cloudy","humidity": "65%"},
        "sydney":    {"temp": "24°C", "condition": "clear",        "humidity": "60%"},
        "dubai":     {"temp": "38°C", "condition": "hot and sunny","humidity": "40%"},
    }
    if city_normalized in weather_database:
        data = weather_database[city_normalized]
        return (
            f"Weather in {city.title()}: "
            f"{data['temp']}, {data['condition']}, "
            f"humidity {data['humidity']}"
        )
    return f"Weather in {city}: 20°C, partly cloudy, humidity 60% (default)"

def web_search(query: str) -> str:
    # WHY THIS EXISTS:
    # GPT cannot access the internet. For current events, news,
    # or specific facts not in training data, we need a real search.
    # In production: use SerpAPI, Tavily, Bing Search API, etc.
    #
    # Simulated results for demonstration:
    simulated_results = {
        "python":         "Python 3.13 released with major performance improvements. JIT compiler added.",
        "openai":         "OpenAI releases GPT-5 with improved reasoning and multimodal capabilities.",
        "artificial intelligence": "AI adoption reaches 80% in Fortune 500 companies in 2025.",
    }
    query_lower = query.lower()
    for keyword, result in simulated_results.items():
        if keyword in query_lower:
            return f"Search results for '{query}': {result}"
    return f"Search results for '{query}': Found 10 relevant articles about {query}. Top result: Recent developments in {query} show significant progress."

def unit_converter(value: float, from_unit: str, to_unit: str) -> str:
    # WHY THIS EXISTS:
    # Unit conversions involve precise multiplication factors.
    # GPT sometimes rounds incorrectly. A real function guarantees precision.
    #
    # The conversion table maps (from, to) → lambda function
    # Lambda takes the input value and returns the converted value
    conversion_table = {
        # Distance
        ("km",          "miles"):       lambda x: x * 0.621371,
        ("miles",       "km"):          lambda x: x * 1.60934,
        ("meters",      "feet"):        lambda x: x * 3.28084,
        ("feet",        "meters"):      lambda x: x * 0.3048,
        # Temperature
        ("celsius",     "fahrenheit"):  lambda x: x * 9/5 + 32,
        ("fahrenheit",  "celsius"):     lambda x: (x - 32) * 5/9,
        # Weight
        ("kg",          "lbs"):         lambda x: x * 2.20462,
        ("lbs",         "kg"):          lambda x: x * 0.453592,
        # Volume
        ("liters",      "gallons"):     lambda x: x * 0.264172,
        ("gallons",     "liters"):      lambda x: x * 3.78541,
    }
    key = (from_unit.lower().strip(), to_unit.lower().strip())
    if key in conversion_table:
        converted = conversion_table[key](value)
        return f"{value} {from_unit} = {converted:.6f} {to_unit} (precise: {converted})"
    return (
        f"Conversion '{from_unit}' → '{to_unit}' not supported. "
        f"Supported: km/miles, celsius/fahrenheit, kg/lbs, meters/feet, liters/gallons"
    )

def summarizer(text: str) -> str:
    # WHY THIS EXISTS:
    # When web_search returns a long block of text, the user might want
    # a condensed version. In production, you'd call GPT itself here
    # with a summarization prompt, or use a dedicated summarization API.
    word_list = text.split()
    total_words = len(word_list)
    if total_words <= 30:
        return f"[Text is already short — no summarization needed]: {text}"
    # Take first 20 words as "key points" (simplified simulation)
    key_points = " ".join(word_list[:20])
    return (
        f"Summary ({total_words} words → key points): {key_points}... "
        f"[{total_words - 20} words omitted]"
    )

# ════════════════════════════════════════════════════════════════
# PART B: The Function Map
# ════════════════════════════════════════════════════════════════
#
# OpenAI tells us the tool name as a STRING (e.g. "calculator").
# We need to go from that string → actual Python function object.
# A dictionary is the perfect structure for this.
#
# When OpenAI says: call "calculator" with args {"expression": "5*5"}
# We do:  FUNCTION_MAP["calculator"](**{"expression": "5*5"})
# Which becomes: calculator(expression="5*5")
# ════════════════════════════════════════════════════════════════

FUNCTION_MAP = {
    "calculator":     calculator,
    "weather_tool":   weather_tool,
    "web_search":     web_search,
    "unit_converter": unit_converter,
    "summarizer":     summarizer,
}

# Verify: print the mapping so you can see it clearly
print("FUNCTION MAP:")
for name, fn in FUNCTION_MAP.items():
    print(f"  '{name}' → {fn.__name__}()")

# ════════════════════════════════════════════════════════════════
# PART C: The Tools Schema (JSON descriptions for OpenAI)
# ════════════════════════════════════════════════════════════════
#
# THIS IS WHAT OPENAI READS TO DECIDE WHICH TOOL TO USE.
# The model CANNOT see your Python code — only this JSON.
# So the description quality directly determines tool selection quality.
#
# STRUCTURE OF EACH TOOL:
# {
#   "type": "function",          ← always "function" for now
#   "function": {
#     "name": "...",             ← MUST match key in FUNCTION_MAP
#     "description": "...",      ← LLM reads this to decide when to use it
#     "parameters": {            ← JSON Schema for the function arguments
#       "type": "object",
#       "properties": {
#         "arg_name": {
#           "type": "string/number/boolean/array",
#           "description": "..."  ← LLM reads this to know what to put here
#         }
#       },
#       "required": ["arg1", "arg2"]  ← which args are mandatory
#     }
#   }
# }
# ════════════════════════════════════════════════════════════════

TOOLS_SCHEMA = [
    {
        "type": "function",
        "function": {
            "name": "calculator",
            # GOOD description: says WHEN to use, WHEN NOT to use
            # BAD description would be: "Does math" (too vague)
            "description": (
                "Evaluates mathematical expressions with precision. "
                "USE THIS for: large number arithmetic, expressions with "
                "many operations, square roots (math.sqrt), powers, etc. "
                "DO NOT USE for: simple mental math like 2+2, 10*5, 100/4. "
                "The LLM can answer those directly without this tool."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "expression": {
                        "type": "string",
                        # This description tells OpenAI HOW to format the argument
                        "description": (
                            "A valid Python math expression as a string. "
                            "Examples: '1234 * 5678', 'math.sqrt(144)', "
                            "'(100 + 200) * 3 / 7', '2 ** 10'. "
                            "Do NOT include '=' sign. Just the expression."
                        )
                    }
                },
                "required": ["expression"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "weather_tool",
            "description": (
                "Retrieves real-time current weather conditions for a city. "
                "USE THIS when: user asks about weather, temperature, or "
                "climate conditions in a specific city RIGHT NOW. "
                "DO NOT USE for: historical weather, weather forecasts, "
                "or general climate information (LLM knows general climate)."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": (
                            "The name of the city in English. "
                            "Examples: 'London', 'New York', 'Tokyo'. "
                            "Use the most common English spelling."
                        )
                    }
                },
                "required": ["city"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "web_search",
            "description": (
                "Searches the internet for current information and recent facts. "
                "USE THIS for: recent news, current events, information after "
                "your training cutoff, specific facts you are NOT confident about. "
                "DO NOT USE for: general knowledge, history, science basics, "
                "math, or anything confidently in your training data."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": (
                            "A clear, specific search query string. "
                            "Examples: 'Python 3.13 new features', "
                            "'latest OpenAI GPT-5 release', "
                            "'current Bitcoin price 2025'. "
                            "Be specific for better results."
                        )
                    }
                },
                "required": ["query"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "unit_converter",
            "description": (
                "Converts values between different units of measurement. "
                "USE THIS when: user explicitly asks to convert units. "
                "Supports: km↔miles, celsius↔fahrenheit, kg↔lbs, "
                "meters↔feet, liters↔gallons. "
                "DO NOT USE for: currency conversion (use web_search), "
                "or when conversion is not explicitly requested."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "value": {
                        "type": "number",
                        "description": "The numeric value to convert. Example: 100 (for 100km)"
                    },
                    "from_unit": {
                        "type": "string",
                        "description": (
                            "The source unit. Must be one of: "
                            "km, miles, celsius, fahrenheit, kg, lbs, meters, feet, liters, gallons"
                        )
                    },
                    "to_unit": {
                        "type": "string",
                        "description": (
                            "The target unit. Must be one of: "
                            "km, miles, celsius, fahrenheit, kg, lbs, meters, feet, liters, gallons"
                        )
                    }
                },
                "required": ["value", "from_unit", "to_unit"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "summarizer",
            "description": (
                "Condenses a long block of text into key points. "
                "USE THIS when: user EXPLICITLY asks for a summary, OR "
                "when you have retrieved a long web search result and need "
                "to condense it before presenting. "
                "DO NOT USE for: short texts under 50 words, or when "
                "the user has not requested summarization."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "text": {
                        "type": "string",
                        "description": (
                            "The full text to be summarized. "
                            "Should be at least 50 words to be worth summarizing. "
                            "Pass the complete original text, not a partial version."
                        )
                    }
                },
                "required": ["text"]
            }
        }
    }
]

print(f"\nTOOLS SCHEMA: {len(TOOLS_SCHEMA)} tools registered")
for t in TOOLS_SCHEMA:
    name = t["function"]["name"]
    params = list(t["function"]["parameters"]["properties"].keys())
    required = t["function"]["parameters"]["required"]
    print(f"  • {name}({', '.join(params)}) — required: {required}")
```
